function merge(a, b) {
  var result = [];
  var i = 0;
  var j = 0;
  while (i < a.length && j < b.length) {
    if (a[i] <= b[j]) {
      result.push(a[i++]);
    } else {
      result.push(b[j++]);
    }
  }
  return result.concat(a.slice(i), b.slice(j));
}

console.log(merge([1, 4, 7], [2, 3, 9, 10]));
